50	/// Signed area of a closed path (shoelace formula), matching Clipper2Lib::Area.
51	/// Positive for counter-clockwise orientation (Cartesian, y-up).
52	pub fn area(path: &Path64) -> f64 {
53	    let n = path.len();
54	    if n < 3 {
55	        return 0.0;
56	    }
57	    let mut a: f64 = 0.0;
58	    for i in 0..n {
59	        let j = if i + 1 == n { 0 } else { i + 1 };
60	        a += path[i].x as f64 * path[j].y as f64 - path[j].x as f64 * path[i].y as f64;
61	    }
62	    a * 0.5
63	}
