66	pub fn get_bounds(paths: &Paths64) -> Rect64 {
67	    let mut r = Rect64 {
68	        left: i64::MAX,
69	        top: i64::MAX,
70	        right: i64::MIN,
71	        bottom: i64::MIN,
72	    };
73	    for path in paths {
74	        for pt in path {
75	            if pt.x < r.left {
76	                r.left = pt.x;
77	            }
78	            if pt.x > r.right {
79	                r.right = pt.x;
80	            }
81	            if pt.y < r.top {
82	                r.top = pt.y;
83	            }
84	            if pt.y > r.bottom {
