//! Polygon offsetting, mirroring Clipper2Lib::InflatePaths. (keep the doc header, implement)

use crate::geom::{EndType, JoinType, Path64, Paths64, Point64};

const DEFAULT_ARC_TOLERANCE: f64 = 0.25;

#[derive(Clone, Copy)]
struct Pt { x: f64, y: f64 } // PointD

fn get_unit_normal(a: Point64, b: Point64) -> Pt {
    let dx = (b.x - a.x) as f64;
    let dy = (b.y - a.y) as f64;
    if dx == 0.0 && dy == 0.0 { return Pt{x:0.0,y:0.0}; }
    let f = 1.0 / dx.hypot(dy);
    Pt { x: dy*f, y: -dx*f }
}

