fn round_i64(v: f64) -> i64 { v.round_ties_even() as i64 } // candidate; switchable

#[derive(Clone, Copy)]
struct PtD { x: f64, y: f64 }

fn get_unit_normal(a: Point64, b: Point64) -> PtD {
    let dx = (b.x - a.x) as f64;
    let dy = (b.y - a.y) as f64;
    if dx == 0.0 && dy == 0.0 { return PtD { x: 0.0, y: 0.0 }; }
    let f = 1.0 / dx.hypot(dy);
    PtD { x: dy * f, y: -dx * f }
}

fn cross_d(a: PtD, b: PtD) -> f64 { a.x * b.y - b.x * a.y }
fn dot_d(a: PtD, b: PtD) -> f64 { a.x * b.x + a.y * b.y }

fn perpendic(pt: Point64, n: PtD, delta: f64) -> Point64 {
    Point64::new(round_i64(pt.x as f64 + n.x * delta), round_i64(pt.y as f64 + n.y * delta))
}
