fn offset_path(path: &Path64, delta: f64, steps_per_360: f64, out: &mut Path64) {
    let cnt = path.len();
    let mut normals: Vec<PtD> = Vec::with_capacity(cnt);
    for i in 0..cnt { normals.push(get_unit_normal(path[i], path[(i+1)%cnt])); }
    let mut k = cnt - 1;
    for j in 0..cnt {
        let sin_a = cross_d(normals[k], normals[j]).clamp(-1.0, 1.0);
        let cos_a = dot_d(normals[j], normals[k]);
        if sin_a * delta < 0.0 {
            out.push(perpendic(path[j], normals[k], delta));
            out.push(path[j]);
            out.push(perpendic(path[j], normals[j], delta));
        } else {
            do_round(out, path[j], normals[k], normals[j], sin_a.atan2(cos_a), delta, steps_per_360);
        }
        k = j;
    }
}

fn do_round(out, pt, n1, n2, angle, delta, steps_per_360) {
    let steps = ((steps_per_360 * angle.abs() / (2π)).ceil() as i32).max(1);
    let step = angle / steps as f64;
    let sn = step.sin(); let cs = step.cos();
    let mut v = n1;
    out.push(perpendic(pt, n1, delta)); // variant C
    for _ in 1..steps {
        v = PtD { x: v.x*cs - sn*v.y, y: v.y*cs + v.x*sn };
        out.push(perpendic(pt, v, delta));
    }
    out.push(perpendic(pt, n2, delta));
}
