// For each positive delta, find (N0, N1, radius-model, rounding) reproducing the oracle area.
use std::f64::consts::PI;

#[derive(Clone, Copy)]
struct P {
    x: f64,
    y: f64,
}

fn unit_normal(ax: i64, ay: i64, bx: i64, by: i64) -> P {
    let dx = (bx - ax) as f64;
    let dy = (by - ay) as f64;
    let f = 1.0 / dx.hypot(dy);
    P { x: dy * f, y: -dx * f }
}

fn ties_even(v: f64) -> i64 {
    let f = v.floor();
    let frac = v - f;
    if frac < 0.5 {
        f as i64
    } else if frac > 0.5 {
        f as i64 + 1
    } else {
        let fi = f as i64;
        if fi % 2 == 0 {
            fi
        } else {
            fi + 1
        }
    }
}

// radius model: 0 = all points at d; 1 = intermediate at d/cos(step/2); 2 = all at d/cos(step/2)
fn arc_pts(
    px: i64,
    py: i64,
    n1: P,
    n2: P,
    a2: f64,
    steps: usize,
    delta: f64,
    even: bool,
    rmodel: usize,
    out: &mut Vec<(i64, i64)>,
) {
    let r = |v: f64| if even { ties_even(v) } else { v.round() as i64 };
    let step = a2 / steps as f64;
    let sn = step.sin();
    let cs = step.cos();
    let rad_mid = delta / (step / 2.0).cos();
    let rad_end = if rmodel == 2 { rad_mid } else { delta };
    let mut push = |v: P, rad: f64| {
        out.push((r(px as f64 + v.x * rad), r(py as f64 + v.y * rad)));
    };
    // variant C: push n1, rot^1..rot^(N-1), n2
    push(n1, rad_end);
    let mut v = n1;
    for _ in 1..steps {
        v = P { x: v.x * cs - sn * v.y, y: v.y * cs + v.x * sn };
        push(v, if rmodel == 0 { delta } else { rad_mid });
    }
    push(n2, rad_end);
}

fn area(pts: &[(i64, i64)]) -> f64 {
    let n = pts.len();
